import{_ as a,o as n,c as t,a2 as s}from"./chunks/framework.BWTY_seE.js";const m=JSON.parse('{"title":"AI 动态 · 2026-11-12","description":"","frontmatter":{"title":"AI 动态 · 2026-11-12","date":"2026-11-12T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-11/ai-news-2026-11-12.md","filePath":"news/2026-11/ai-news-2026-11-12.md","lastUpdated":null}'),r={name:"news/2026-11/ai-news-2026-11-12.md"};function i(o,e,l,c,p,d){return n(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-11-12" tabindex="-1">AI 动态 · 2026-11-12 <a class="header-anchor" href="#ai-动态-·-2026-11-12" aria-label="Permalink to &quot;AI 动态 · 2026-11-12&quot;">​</a></h1><blockquote><p>截至 2026-11-12。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-briefing" data-section="今日导读"><h2 id="今日导读" tabindex="-1">今日导读 <a class="header-anchor" href="#今日导读" aria-label="Permalink to &quot;今日导读&quot;">​</a></h2><ol><li>今日最大变量来自英伟达：黄仁勋辞去CEO，CFO Colette Kress出任临时CEO，AI算力格局进入不确定期。</li><li>模型侧Google发布Gemini Decisions API与Gemini Decision 1，以每百万输入token 0.10美元切入决策模型赛道，与Jev、OpenAI正面竞争。</li><li>产品与开发者侧Claude密集更新（Opus 5.5成默认、自托管Managed Agents、Claude Meetings），Agent安全与工程化成为主线。</li></ol></div><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="头条-·-认识英伟达新任临时ceo-colette-kress" tabindex="-1">头条 · 认识英伟达新任临时CEO Colette Kress <a class="header-anchor" href="#头条-·-认识英伟达新任临时ceo-colette-kress" aria-label="Permalink to &quot;头条 · 认识英伟达新任临时CEO Colette Kress&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Wired AI</span><time datetime="2026-11-12">2026-11-12</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/2d85df1cc7f6.jpg" alt="配图"></p><p>Kress长期担任英伟达CFO，是推动公司成为AI算力巨头的关键财务操盘者，如今在黄仁勋辞职后接掌帅印。她的财务与资本配置背景，意味着过渡期公司策略可能更偏向稳健运营与投资者沟通。对读者：与其追逐人事八卦，不如跟踪其上任后的资本开支与产能指引，这直接决定GPU供给节奏。</p><p class="news-entry-source"><a href="https://www.wired.com/story/who-is-colette-kress-the-woman-who-could-succeed-jensen-huang/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="台积电拟向anthropic与openai各投资10亿美元" tabindex="-1">台积电拟向Anthropic与OpenAI各投资10亿美元 <a class="header-anchor" href="#台积电拟向anthropic与openai各投资10亿美元" aria-label="Permalink to &quot;台积电拟向Anthropic与OpenAI各投资10亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Ars Technica AI</span><time datetime="2026-11-12">2026-11-12</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/96424419ad1b.jpg" alt="配图"></p><p>报道称台积电将向Anthropic和OpenAI投资10亿美元，成为AI热潮中「循环融资」的最新案例，而此刻AI交易本身正出现波动。芯片制造龙头直接入股模型公司，强化了算力与模型的绑定关系。对读者：关注这类交叉持股对算力定价与优先供货的影响，评估自身模型供应商的供应链稳定性。</p><p class="news-entry-source"><a href="https://arstechnica.com/ai/2026/11/taiwans-chipmaking-giant-tsmc-to-invest-1b-in-anthropic-openai/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="norwest设立40亿美元新基金加码ai" tabindex="-1">Norwest设立40亿美元新基金加码AI <a class="header-anchor" href="#norwest设立40亿美元新基金加码ai" aria-label="Permalink to &quot;Norwest设立40亿美元新基金加码AI&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-12">2026-11-12</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/e6a058001264.webp" alt="配图"></p><p>投资机构Norwest宣布成立规模40亿美元的新基金，为其史上最大一只基金，明确将更深入押注AI领域。在一级市场对AI估值分歧加大的背景下，这代表头部VC仍在加仓。对读者：创业者可关注其投资偏好与阶段，融资窗口期或许比想象中更宽。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/12/norwest-pushes-deeper-into-ai-with-new-4b-fund/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="fireworks-ai遭攻击-notion客户聊天记录外泄" tabindex="-1">Fireworks AI遭攻击，Notion客户聊天记录外泄 <a class="header-anchor" href="#fireworks-ai遭攻击-notion客户聊天记录外泄" aria-label="Permalink to &quot;Fireworks AI遭攻击，Notion客户聊天记录外泄&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-12">2026-11-12</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/a71d7637774b.jpg" alt="配图"></p><p>Fireworks AI存储系统遭网络攻击，导致Notion客户的AI聊天记录被黑客访问，且这些数据存放在零数据保留策略之外。这是Fireworks两个月内的第二起数据泄露。对读者：使用第三方推理服务时务必确认数据留存与隔离策略，零数据保留承诺需以合同与审计验证。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/12/cyberattack-on-fireworks-ai-allowed-hackers-to-access-notion-customers-chat-transcripts/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="google-gemini智能眼镜发布-起售价395美元" tabindex="-1">Google Gemini智能眼镜发布，起售价395美元 <a class="header-anchor" href="#google-gemini智能眼镜发布-起售价395美元" aria-label="Permalink to &quot;Google Gemini智能眼镜发布，起售价395美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Ars Technica AI</span><time datetime="2026-11-12">2026-11-12</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/4a3f90cf6381.jpg" alt="配图"></p><p>首批Gemini智能眼镜由Google联合三星、Gentle Monster与Warby Parker推出，起售价395美元，Google同步强调隐私设计。这是Gemini从软件走向硬件的关键一步，也把AI眼镜价格拉到中端区间。对读者：若考虑AI眼镜产品选型，可关注其隐私处理与生态兼容性，而非仅看价格。</p><p class="news-entry-source"><a href="https://arstechnica.com/google/2026/11/google-pushes-privacy-angle-as-gemini-powered-smartglasses-debut-starting-at-395/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="claude-opus-5-5成为pro-max-team默认模型" tabindex="-1">Claude Opus 5.5成为Pro/Max/Team默认模型 <a class="header-anchor" href="#claude-opus-5-5成为pro-max-team默认模型" aria-label="Permalink to &quot;Claude Opus 5.5成为Pro/Max/Team默认模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Claude Blog</span><time datetime="2026-11-12">2026-11-12</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/d385dcf0fcef.webp" alt="配图"></p><p>Anthropic宣布Opus 5.5成为Claude在Pro、Max、Ultra与Team套餐中的默认模型，并给出其与其他模型在知识工作任务上的对比与使用建议。默认模型升级意味着现有用户无需改配置即可获得更强推理能力。对读者：团队可重新评估哪些知识工作流可交给默认模型，同时留意用量与成本变化。</p><p class="news-entry-source"><a href="https://claude.com/resources/articles/using-claude-opus-5-5-as-your-daily-driver-for-knowledge-work" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="claude-managed-agents支持自托管-进入私有测试" tabindex="-1">Claude Managed Agents支持自托管，进入私有测试 <a class="header-anchor" href="#claude-managed-agents支持自托管-进入私有测试" aria-label="Permalink to &quot;Claude Managed Agents支持自托管，进入私有测试&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Claude Blog</span><time datetime="2026-11-12">2026-11-12</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/d1dc039bd00b.webp" alt="配图"></p><p>Anthropic推出自托管版Claude Managed Agents私有测试，用户可在自有云或本地环境运行Agent，自行托管Agent、凭证与会话历史，并选择请求发送至Claude的位置。这直接回应企业对数据主权与合规的诉求。对读者：受监管行业团队可申请测试，重点验证凭证管理与审计链路。</p><p class="news-entry-source"><a href="https://claude.com/resources/articles/self-hosted-claude-managed-agents" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="claude-meetings发布-开会时同步产出文档与白板" tabindex="-1">Claude Meetings发布：开会时同步产出文档与白板 <a class="header-anchor" href="#claude-meetings发布-开会时同步产出文档与白板" aria-label="Permalink to &quot;Claude Meetings发布：开会时同步产出文档与白板&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Claude Blog</span><time datetime="2026-11-12">2026-11-12</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/798ffdf137ef.webp" alt="配图"></p><p>Claude Meetings进入beta，可将Claude加入视频会议，实时记笔记、回答问题，并在团队讨论时同步构建文档与白板。它把AI从会后总结前移到会中协作。对读者：可先在低风险会议中试用，评估记录准确性与敏感信息处理策略。</p><p class="news-entry-source"><a href="https://claude.com/resources/articles/claude-meetings" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="claude-for-manufacturing发布-17项技能-4个连接器" tabindex="-1">Claude for Manufacturing发布：17项技能+4个连接器 <a class="header-anchor" href="#claude-for-manufacturing发布-17项技能-4个连接器" aria-label="Permalink to &quot;Claude for Manufacturing发布：17项技能+4个连接器&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Claude Blog</span><time datetime="2026-11-12">2026-11-12</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/c5c3039fd00f.webp" alt="配图"></p><p>Anthropic推出制造业插件，包含17项技能与4个连接器，可基于工厂既有系统起草报价、质量报告与供应商请求，供团队审核批准。这是Claude向垂直行业深水区延伸的信号。对读者：制造企业可评估其与现有ERP/MES的对接成本，优先在文档密集型环节试点。</p><p class="news-entry-source"><a href="https://claude.com/resources/articles/claude-for-manufacturing" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="holiday-extras用codex重构应用开发" tabindex="-1">Holiday Extras用Codex重构应用开发 <a class="header-anchor" href="#holiday-extras用codex重构应用开发" aria-label="Permalink to &quot;Holiday Extras用Codex重构应用开发&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-11-12">2026-11-12</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/6682e06e3221.png" alt="配图"></p><p>OpenAI发布案例，Holiday Extras借助Codex把客户专业知识转化为更好的应用，提升预订转化率并打开增长空间。案例显示编码助手正从个人提效走向业务指标改善。对读者：评估编码助手时，可把转化率、交付周期等业务指标纳入ROI测算。</p><p class="news-entry-source"><a href="https://openai.com/business/customer-stories/holidays-extras-codex" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="google发布gemini-decisions-api-gemini-decision-1定价0-10美元-百万token" tabindex="-1">Google发布Gemini Decisions API，Gemini Decision 1定价0.10美元/百万token <a class="header-anchor" href="#google发布gemini-decisions-api-gemini-decision-1定价0-10美元-百万token" aria-label="Permalink to &quot;Google发布Gemini Decisions API，Gemini Decision 1定价0.10美元/百万token&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-12">2026-11-12</time></p><p>Google推出Gemini Decisions API，由Gemini Decision 1驱动，可对最多1000个是/否、选择与评分制问题返回校准概率，覆盖文本、图像、音频、视频与PDF，输入定价为每百万token 0.10美元。决策模型赛道再添一员。对读者：分类与审核类任务可对比其与Jev、OpenAI决策模型的成本与多模态覆盖。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/11/google-gemini-decisions-api-gemini-decision-1/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="simon-willison评gemini-decisions-api-多模态是差异点" tabindex="-1">Simon Willison评Gemini Decisions API：多模态是差异点 <a class="header-anchor" href="#simon-willison评gemini-decisions-api-多模态是差异点" aria-label="Permalink to &quot;Simon Willison评Gemini Decisions API：多模态是差异点&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Simon Willison</span><time datetime="2026-11-12">2026-11-12</time></p><p>Willison指出Gemini Decision 1与Jev高度相似，同样支持是/否、选择与评分三类问题，定价与GPT-6 Luna决策模型一致为每百万输入token 10美分且输出免费；Jev仍最便宜为4.2美分，但Gemini覆盖文本、图像、音频等多模态。对读者：选型时按模态需求与单价权衡，纯文本场景Jev仍有成本优势。</p><p class="news-entry-source"><a href="https://simonwillison.net/2026/Nov/11/gemini-decisions-api/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="deepmind发布alphagenome-2-预测细胞类型特异性变异效应" tabindex="-1">DeepMind发布AlphaGenome 2，预测细胞类型特异性变异效应 <a class="header-anchor" href="#deepmind发布alphagenome-2-预测细胞类型特异性变异效应" aria-label="Permalink to &quot;DeepMind发布AlphaGenome 2，预测细胞类型特异性变异效应&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-12">2026-11-12</time></p><p>Google DeepMind发布AlphaGenome 2，这是一个条件DNA序列模型，可预测每种细胞类型的调控活性与变异效应，并通过AlphaGenome API面向非商业研究开放。AI for Science再进一步。对读者：生物信息团队可申请API验证其在靶点与变异解读上的可用性。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/11/google-deepmind-alphagenome-2-cell-type-variant-effects/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="ibm发布quantum-nighthawk-r3-520量子比特支持1万次量子操作" tabindex="-1">IBM发布Quantum Nighthawk r3：520量子比特支持1万次量子操作 <a class="header-anchor" href="#ibm发布quantum-nighthawk-r3-520量子比特支持1万次量子操作" aria-label="Permalink to &quot;IBM发布Quantum Nighthawk r3：520量子比特支持1万次量子操作&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-12">2026-11-12</time></p><p>IBM公布Quantum Nighthawk r3处理器，520个可编程量子比特，设计支持1万次量子操作；2027年将有两颗r3芯片互联成1040量子比特系统，Nighthawk r2相较Heron最高实现19倍加速。对读者：量子计算仍属长周期投入，可关注其与经典AI工作负载的结合点而非短期替代。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/12/ibm-quantum-nighthawk-r3-520-qubits-1040-qubit-system-2027/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="openai详解如何保障openclaw等持久化agent安全" tabindex="-1">OpenAI详解如何保障OpenClaw等持久化Agent安全 <a class="header-anchor" href="#openai详解如何保障openclaw等持久化agent安全" aria-label="Permalink to &quot;OpenAI详解如何保障OpenClaw等持久化Agent安全&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Developer</span><time datetime="2026-11-12">2026-11-12</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/1b4ee010e905.webp" alt="配图"></p><p>OpenAI介绍其运行持久化Agent的安全组合：可信控制平面服务、Codex沙箱、自动审查、Agent身份与可观测性。这为自建Agent的团队提供了可参考的防护分层。对读者：设计Agent时优先补齐身份、沙箱与审计三件套，再谈能力扩展。</p><p class="news-entry-source"><a href="https://developers.openai.com/blog/securing-persistent-agents-like-openclaw-at-openai" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="aws用a2a协议构建可组合多agent系统" tabindex="-1">AWS用A2A协议构建可组合多Agent系统 <a class="header-anchor" href="#aws用a2a协议构建可组合多agent系统" aria-label="Permalink to &quot;AWS用A2A协议构建可组合多Agent系统&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">AWS Machine Learning</span><time datetime="2026-11-12">2026-11-12</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/bde8774e065b.png" alt="配图"></p><p>AWS发布教程，演示用Agent-to-Agent（A2A）协议跨组织边界构建多Agent系统：Amazon ECS上的LangChain编排器与Bedrock AgentCore上的Strands Agent通过双向OAuth认证调用，双方不依赖彼此框架或SDK。对读者：跨团队Agent协作可优先评估A2A这类开放协议，降低框架锁定。</p><p class="news-entry-source"><a href="https://aws.amazon.com/blogs/machine-learning/build-composable-interoperable-multi-agent-systems-with-a2a-on-aws/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="aws推出官方aws-emulator-本地测试无需付费api-key" tabindex="-1">AWS推出官方aws-emulator，本地测试无需付费API Key <a class="header-anchor" href="#aws推出官方aws-emulator-本地测试无需付费api-key" aria-label="Permalink to &quot;AWS推出官方aws-emulator，本地测试无需付费API Key&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Simon Willison</span><time datetime="2026-11-12">2026-11-12</time></p><p>AWS发布官方模拟器aws-emulator，可在本地克隆多项AWS服务进行测试，无需开通付费API Key。该项目用Rust编写，由大量Agent协作完成，前三周提交达29684次；目前在macOS与Windows上仍需Docker。对读者：CI中引入本地模拟可显著降低测试成本，但需评估Docker依赖带来的环境复杂度。</p><p class="news-entry-source"><a href="https://simonwillison.net/2026/Nov/11/aws-emulator/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="meta开源八年设计系统astryx-连坐两天github总榜第一" tabindex="-1">Meta开源八年设计系统astryx，连坐两天GitHub总榜第一 <a class="header-anchor" href="#meta开源八年设计系统astryx-连坐两天github总榜第一" aria-label="Permalink to &quot;Meta开源八年设计系统astryx，连坐两天GitHub总榜第一&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">掘金前端</span><time datetime="2026-11-12">2026-11-12</time></p><p>Meta开源其使用八年的设计系统astryx，一套React组件库，连续两天位居GitHub总榜第一。其README明确面向「人，以及和人一起干活的agent」，组件库开始为Agent编写说明书。对读者：前端团队可研究其面向Agent的文档组织方式，为自家组件库的AI可读性做改造。</p><p class="news-entry-source"><a href="https://juejin.cn/post/7707184266060300322" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="css-anchor-positioning已进baseline-弹层不必再手算坐标" tabindex="-1">CSS Anchor Positioning已进Baseline：弹层不必再手算坐标 <a class="header-anchor" href="#css-anchor-positioning已进baseline-弹层不必再手算坐标" aria-label="Permalink to &quot;CSS Anchor Positioning已进Baseline：弹层不必再手算坐标&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">掘金前端</span><time datetime="2026-11-12">2026-11-12</time></p><p>CSS Anchor Positioning已于2026年1月成为Baseline，文章从锚点、翻转、Popover到列表场景讲清原理与可上线路径。弹层定位不必再依赖getBoundingClientRect与滚动监听。对读者：新项目可直接采用，老项目可先在非关键弹层灰度替换，减少坐标计算代码。</p><p class="news-entry-source"><a href="https://juejin.cn/post/7707147434673127439" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div>',9)])])}const g=a(r,[["render",i]]);export{m as __pageData,g as default};
